@startuml

class User {
  + id : string
  + name : string
  + email : string
  + dateOfBirth : date
}

class Account {
  + accountNumber : long
}

class BusinessAccount extends Account {
  + companyName : string
  + monthlyFee : double
}

class PersonalAccount extends Account {}

class Page {
  + pageName : string
  + numberOfVisits : int
}

class AdvertisementPage extends Page {
  + bounceRate : float
  + clickThroughRate : float
  + conversionRate : float
}

User "1" -- "0..1" Account : has

Account "1" -- "*" Page : creates

PersonalAccount "0..1" -- "*" Page : is granted privileges to

@enduml

